import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int targetRow = 0;int targetCol = 0;for (int i = 1; i <= 5; i++) {String line = br.readLine();if (line == null) break;StringTokenizer st = new StringTokenizer(line);for (int j = 1; j <= 5; j++) {if (Integer.parseInt(st.nextToken()) == 1) {targetRow = i;targetCol = j;}}}int moves = Math.abs(targetRow - 3) + Math.abs(targetCol - 3);System.out.println(moves);}}